#!/usr/bin/env bash
# Creates the secrets in AWS Secrets Manager (owner: Joseph; Resend: Youssef). Safe to run again.
#   roadhub/jwt-private  RS256 private key: ONLY the admin service may read it (it signs logins)
#   roadhub/jwt-public   RS256 public key: every service reads it to CHECK logins
#   roadhub/internal     key for service-to-service tokens
#   roadhub/resend       Resend API key (from infra/.env, never typed into the code)
#   roadhub/turnstile    Cloudflare Turnstile secret key (test key by default)
# Values are generated by Node or read from infra/.env; they are never printed.
source "$(dirname "$0")/../lib.sh"
step "Secrets Manager"
[ -f "$ROOT_DIR/infra/.env" ] && set -a && . <(sed 's/\r$//' "$ROOT_DIR/infra/.env") && set +a
node "$ROOT_DIR/infra/scripts/create-secrets.js"
